describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = { stripeApiKey: 'sk_test_123', fetch }
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotContactPayload, config)
