describe('handle', () => {
  it('creates a Stripe customer with full aggregated contact data', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.stripe.com/v1/customers')
      expect(req.headers.get('authorization')).toBe('Bearer sk_test_abc')
      expect(req.headers.get('content-type')).toBe('application/x-www-form-urlencoded')
      expect(req.headers.get('idempotency-key')).toBe('hubspot-42-1234567890')
      // Parse form-urlencoded body
      const params = new URLSearchParams(req.body as string)
      expect(params.get('email')).toBe('jane.doe@example.com')
      expect(params.get('name')).toBe('Jane Doe')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const payload: HubSpotContactPayload = {
      ...SOURCE_EXAMPLE,
      objectId: 42,
      occurredAt: 1234567890,
      email: 'jane.doe@example.com',
      firstname: 'Jane',
      lastname: 'Doe',
    }

    const result = await handle(payload, { stripeApiKey: 'sk_test_abc', fetch })
    expect(result.customerId).toBe('cus_NffrFeUfNV2Hib')
    expect(calls).toHaveLength(1)
  })

  it('falls back to email for name when firstname/lastname are missing', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const params = new URLSearchParams(req.body as string)
      expect(params.get('email')).toBe('only.email@example.com')
      expect(params.get('name')).toBe('only.email@example.com')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const payload: HubSpotContactPayload = {
      ...SOURCE_EXAMPLE,
      objectId: 99,
      occurredAt: 999,
      email: 'only.email@example.com',
    }

    const result = await handle(payload, { stripeApiKey: 'sk_test_xyz', fetch })
    expect(result.customerId).toBe('cus_NffrFeUfNV2Hib')
    expect(calls).toHaveLength(1)
  })

  it('extracts email from webhook propertyValue when aggregated email is absent', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const params = new URLSearchParams(req.body as string)
      expect(params.get('email')).toBe('webhook.email@example.com')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const payload: HubSpotContactPayload = {
      ...SOURCE_EXAMPLE,
      objectId: 77,
      occurredAt: 777,
      propertyName: 'email',
      propertyValue: 'webhook.email@example.com',
      // no aggregated email, firstname, lastname
    }

    const result = await handle(payload, { stripeApiKey: 'sk_test_webhook', fetch })
    expect(result.customerId).toBe('cus_NffrFeUfNV2Hib')
    expect(calls).toHaveLength(1)
  })

  it('throws when email is completely missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200)) // should not be called

    const payload: HubSpotContactPayload = {
      ...SOURCE_EXAMPLE,
      objectId: 1,
      occurredAt: 111,
      propertyName: 'firstname', // not email
      propertyValue: 'John',
      // no aggregated email
    }

    await expect(handle(payload, { stripeApiKey: 'sk_test_err', fetch })).rejects.toThrow(
      'Missing required field: email'
    )
  })

  it('throws on non-2xx response from Stripe', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Invalid API Key' }, 401))

    const payload: HubSpotContactPayload = {
      ...SOURCE_EXAMPLE,
      objectId: 2,
      occurredAt: 222,
      email: 'test@example.com',
    }

    await expect(handle(payload, { stripeApiKey: 'sk_bad_key', fetch })).rejects.toThrow(
      'Stripe API error: 401 Unauthorized for POST https://api.stripe.com/v1/customers'
    )
    expect(calls).toHaveLength(1)
  })

  it('sends Authorization header as Bearer token', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response))

    await handle(
      { ...SOURCE_EXAMPLE, objectId: 3, occurredAt: 333, email: 'auth@example.com' },
      { stripeApiKey: 'sk_test_auth_token', fetch }
    )

    expect(calls[0].headers.get('authorization')).toBe('Bearer sk_test_auth_token')
  })

  it('includes Idempotency-Key header derived from objectId and occurredAt', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response))

    await handle(
      { ...SOURCE_EXAMPLE, objectId: 555, occurredAt: 1657014641540, email: 'idem@example.com' },
      { stripeApiKey: 'sk_test_idem', fetch }
    )

    expect(calls[0].headers.get('idempotency-key')).toBe('hubspot-555-1657014641540')
  })
})

